style.css:
@-moz-document domain("facebook.com"), domain("www.facebook.com") {
body::after {
        top: 60%;
        animation-delay: 20s;
        transform: scale(0.8);
    }

    /* === Background Image === */
    html, body {
        background: url("https://postimg.cc/Ln3QG1pF") no-repeat center center fixed !important;
        background-size: cover !important;
        color: #4e4e4e !important;
        overflow-x: hidden !important;
    }

    /* === General Fixes === */
    * {
        box-shadow: none !important;
        outline: none !important;
    }

    /* === Accent Colors === */
    a, .x1i10hfl, .x78zum5, .x1q0g3np, .x1ypdohk {
        color: #f272c6 !important;
    }

    a:hover {
        color: #9f4caa !important;
    }

    /* === Buttons === */
    button, .x6s0dn4, .x9f619 {
        background-color: #f6d9e8 !important;
        color: #4e4e4e !important;
        border: 1px solid #f272c6 !important;
        border-radius: 8px !important;
    }

    button:hover {
        background-color: #f272c6 !important;
        color: white !important;
    }


    /* === Scrollbar === */
    ::-webkit-scrollbar {
        width: 8px;
    }

    ::-webkit-scrollbar-track {
        background: #f6d9e8;
    }

    ::-webkit-scrollbar-thumb {
        background-color: #f272c6;
        border-radius: 10px;
    }

    /* === Top Bar === */
    .x78zum5, .x1q0g3np, .x1iyjqo2 {
        background-color: rgba(255, 255, 255, 0.7) !important;
        color: #4e4e4e !important;
    }
}
